insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values ((select current_version_id from assessments where slug = 'social-cognition-assessment'), 'Social Reasoning', 'Understanding misunderstandings, persuasion, and pretense — situations that require tracking what someone else believes or intends, separate from what''s actually true.', 'Read each short scenario, then choose the explanation that best accounts for the character''s behavior.', NULL, false, 0.5, 2);
